void seq_put_decimal_ll(struct seq_file *m, char delimiter, long long num)
{
	if (num < 0) {
		if (m->count + 3 >= m->size) {
			seq_set_overflow(m);
			return;
		}
		if (delimiter)
			m->buf[m->count++] = delimiter;
		num = -num;
