input.content:
/*
 * Executable boundary test for the CVE-2021-33909 guard added to
 * seq_buf_alloc() in fs/seq_file.c.
 *
 * The body of seq_buf_alloc() below is copied verbatim from the candidate
 * worktree file .patch-port/results/candidate-worktree/fs/seq_file.c
 * (lines 26-46 after the fix), with only the kernel primitives stubbed so it
 * can run in userspace.  It exercises the positive path (size within range)
 * and the negative path (size > MAX_RW_COUNT, the condition the reference fix
 * blocks) and checks that the over-limit paths never reach an allocator.
 */
#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

#define PAGE_SIZE 4096UL
/* include/linux/fs.h: #define MAX_RW_COUNT (INT_MAX & PAGE_CACHE_MASK) */
#define MAX_RW_COUNT (INT_MAX & ~(PAGE_SIZE - 1))
#define GFP_KERNEL 0x10u
#define __GFP_NORETRY 0x4000u
#define __GFP_NOWARN 0x2000u
#define unlikely(x) __builtin_expect(!!(x), 0)
typedef unsigned int gfp_t;

static int alloc_calls;
static unsigned long last_alloc_size;

static void *fake_kmalloc(size_t n, gfp_t g)
{
	(void)g;
	alloc_calls++;
	last_alloc_size = (unsigned long)n;
	return malloc(n ? n : 1);
}
static void *fake_vmalloc(size_t n)
{
	alloc_calls++;
	last_alloc_size = (unsigned long)n;
	return malloc(n ? n : 1);
}
#define kmalloc(n, g) fake_kmalloc((n), (g))
#define vmalloc(n) fake_vmalloc(n)

/* ---- verbatim seq_buf_alloc from candidate worktree fs/seq_file.c ---- */
static void *seq_buf_alloc(unsigned long size)
{
	void *buf;
	gfp_t gfp = GFP_KERNEL;

	if (unlikely(size > MAX_RW_COUNT))
		return NULL;

	/*
	 * For high order allocations, use __GFP_NORETRY to avoid oom-killing -
	 * it's better to fall back to vmalloc() than to kill things.  For small
	 * allocations, just use GFP_KERNEL which will oom kill, thus no need
	 * for vmalloc fallback.
	 */
	if (size > PAGE_SIZE)
		gfp |= __GFP_NORETRY | __GFP_NOWARN;
	buf = kmalloc(size, gfp);
	if (!buf && size > PAGE_SIZE)
		buf = vmalloc(size);
	return buf;
}
/* ----------------------------------------------------------------------- */

static int failures;

static void check(const char *name, unsigned long size, int expect_null)
{
	void *p;

	alloc_calls = 0;
	last_alloc_size = 0;
	p = seq_buf_alloc(size);
	printf("  size=0x%016lx (%lu): returned %s, alloc_calls=%d\n",
	       size, size, p ? "buffer" : "NULL", alloc_calls);
	if (expect_null) {
		if (p != NULL || alloc_calls != 0) {
			printf("    FAIL: over-limit request reached allocator or returned a buffer\n");
			failures++;
		}
	} else {
		if (p == NULL || alloc_calls == 0) {
			printf("    FAIL: in-range request was not allocated\n");
			failures++;
		}
	}
	free(p);
}

int main(void)
{
	printf("MAX_RW_COUNT = 0x%08x (%u)\n", (unsigned)MAX_RW_COUNT, (unsigned)MAX_RW_COUNT);

	/* positive paths: small, page-sized and exactly the cap */
	check("zero", 0UL, 0);
	check("one", 1UL, 0);
	check("page", PAGE_SIZE, 0);
	check("page+1", PAGE_SIZE + 1UL, 0);
	check("max_rw_count", (unsigned long)MAX_RW_COUNT, 0);

	/* negative paths: one over the cap, 2GiB and a fully overflowed size_t */
	check("max_rw_count+1", (unsigned long)MAX_RW_COUNT + 1UL, 1);
	check("2gii", (1UL << 31), 1);
	check("ulong_max", ~0UL, 1);

	printf("%s (%d failure(s))\n", failures ? "RESULT: FAIL" : "RESULT: PASS", failures);
	return failures ? 1 : 0;
}

